 (part_number,name,description,engine_models,technical_group,source_name,source_url,source_note,verification_status,application_type,application_evidence,application_source_url)
values
('106-9873','گروه پمپ روغن موتور Cat 106-9873','Cat Parts Store lists Engine Oil Pump Group for Marine Engine 3516, 3508, 3412, 3516B, 3516C and 3512B; Marine Auxiliary 3608 and 3516B. Generator, industrial and other non-marine applications are also listed.','{3412,3508,3512B,3516,3516B,3516C,3608}','موتورهای دریایی - روغن‌کاری و پمپ روغن','Cat Parts Store','https://parts.cat.com/en/catcorp/product/106-9873','Compatible Models explicitly includes Marine Engine and Marine Auxiliary as well as generator, industrial and equipment applications.','REFERENCE','BOTH','Marine Engine/Auxiliary and non-marine Generator, Industrial, Truck and Wheel Loader applications are listed.','https://parts.cat.com/en/catcorp/product/106-9873'),
('0R-4345','پمپ روغن موتور بازسازی‌شده Cat 0R-4345','Cat Reman Engine Oil Pump; Cat lists Marine Auxiliary 3516C/3516B and Marine Engine 3516/3516B/3516C/3512B, plus generator, vehicular, industrial and petroleum applications.','{3512B,3516,3516B,3516C}','موتورهای دریایی - روغن‌کاری و پمپ روغن','Cat Parts Store','https://parts.cat.com/en/catcorp/product/0R-4345','Official Compatible Models lists marine and non-marine application groups.','REFERENCE','BOTH','Marine Engine/Auxiliary plus Generator Set, Vehicular Engine, Industrial Engine, Petroleum Engine and Truck.','https://parts.cat.com/en/catcorp/product/0R-4345'),
('298-2020','لوله خطوط سوخت Cat 298-2020','Cat Fuel Lines Tube transfers fuel from the fuel filter to the engine; Compatible Models lists Marine Auxiliary C32 and Marine Engine C32.','{C32}','موتورهای دریایی - سیستم سوخت و لوله‌ها','Cat Parts Store','https://parts.cat.com/en/catcorp/product/298-2020','Official Compatible Models lists Marine Auxiliary C32 and Marine Engine C32.','REFERENCE','MARINE','Only Marine Auxiliary C32 and Marine Engine C32 are listed in the checked Compatible Models section.','https://parts.cat.com/en/catcorp/product/298-2020'),
('116-6965','مجموعه پمپ Cat 116-6965','Cat Parts Store lists Pump Group 116-6965 compatible with Marine Engine C280-6. Gas Engine G3612 and G3616 are also listed.','{C280-6}','موتورهای دریایی - پمپ و انتقال سیال','Cat Parts Store','https://parts.cat.com/en/catcorp/product/116-6965','Compatible Models explicitly lists Marine Engine C280-6 and Gas Engine G3612/G3616.','REFERENCE','BOTH','Marine Engine C280-6 and non-marine Gas Engine G3612/G3616 are listed.','https://parts.cat.com/en/catcorp/product/116-6965'),
('240-8297','پمپ سوخت دنده‌ای تک‌مرحله Cat 240-8297','Cat One Section Gear Basic Fuel Pump; Compatible Models lists Marine Engine C280-16/C280-12, Gen Set Engine C280-16/3616 and Petroleum Engine C280-12.','{C280-12,C280-16,3616}','موتورهای دریایی - سیستم سوخت و پمپ','Cat Parts Store','https://parts.cat.com/en/catcorp/product/240-8297','Official page identifies a basic fuel pump and marine C280 plus generator and petroleum engine fitment.','REFERENCE','BOTH','Marine Engine C280-16/C280-12 and non-marine Gen Set Engine/Petroleum Engine applications are listed.','https://parts.cat.com/en/catcorp/product/240-8297'),
('4P-5638','پمپ روغن موتور Cat 4P-5638','Cat Engine Oil 2 Section Gear Pump; Compatible Models lists Marine Engine 3512C, 3516, 3512, 3508B, 3516B, 3512B and Marine Auxiliary 3512C/3512B/3512, plus industrial and truck applications.','{3508B,3512,3512B,3512C,3516,3516B}','موتورهای دریایی - روغن‌کاری و پمپ روغن','Cat Parts Store','https://parts.cat.com/en/catcorp/product/4P-5638','Official Compatible Models lists Marine Engine and Marine Auxiliary as well as non-marine fitments.','REFERENCE','BOTH','Marine Engine/Auxiliary plus Industrial Engine, Truck, Wheel Loader and Generator Set.','https://parts.cat.com/en/catcorp/product/4P-5638'),
('7W-0050','کاور پمپ روغن Cat 7W-0050','Cat Oil Pump Cover; Compatible Models lists Marine Auxiliary and Marine Engine 3500-series models as well as multiple land machines, Generator Set and Industrial/Petroleum Engine applications.','{3508,3508B,3508C,3512,3512B,3512C,3512E,3516,3516B,3516C,3516E}','موتورهای دریایی - روغن‌کاری و کاور پمپ','Cat Parts Store','https://parts.cat.com/en/catcorp/product/7W-0050','Official Compatible Models lists both Marine groups and non-marine equipment/engine classes.','REFERENCE','BOTH','Marine Engine/Auxiliary and land machines, Generator Set, Industrial Engine, Petroleum Engine and Truck.','https://parts.cat.com/en/catcorp/product/7W-0050'),
('7E-3975','دسته پمپ پرایمینگ سوخت Cat 7E-3975','Cat Fuel Priming Pump Handle supports manual fuel priming; Compatible Models lists Marine Engine 3616, 3612 and C280-16/-12/-6/-8, Marine Auxiliary 3608, plus generator, locomotive and petroleum engine applications.','{C280-6,C280-8,C280-12,C280-16,3608,3612,3616}','موتورهای دریایی - سیستم سوخت و پرایمینگ','Cat Parts Store','https://parts.cat.com/en/catcorp/product/7E-3975','Official Compatible Models includes Marine Engine and Marine Auxiliary plus Gen Set, Locomotive and Petroleum Engine.','REFERENCE','BOTH','Marine Engine/Auxiliary and non-marine Gen Set Engine, Locomotive Engine, Petroleum Engine and Gen Set-Military.','https://parts.cat.com/en/catcorp/product/7E-3975'),
('4W-9297','چرخ‌دنده پمپ انتقال سوخت Cat 4W-9297','Cat identifies 4W-9297 as Fuel Transfer Pump Gear; Compatible Models lists Marine Engine C280-16, 3616, 3612 and C280-12, plus Gen Set Engine C280-16/3616 and Petroleum Engine C280-12.','{C280-12,C280-16,3612,3616}','موتورهای دریایی - سیستم سوخت و پمپ انتقال','Cat Parts Store','https://parts.cat.com/en/catcorp/product/4W-9297','Official Compatible Models lists Marine Engine and non-marine generator/petroleum engine applications.','REFERENCE','BOTH','Marine Engine and Gen Set Engine/Petroleum Engine are listed.','https://parts.cat.com/en/catcorp/product/4W-9297'),
('221-0131','مجموعه پمپ پرایمینگ Cat 221-0131','Cat Parts Store lists Pump Group-Priming 221-0131 compatible with Marine Engine C280-16, C280-12 and C280-8, plus Gen Set Engine C280-16/3616 and Petroleum Engine C280-12.','{C280-8,C280-12,C280-16,3608,3606,3616}','موتورهای دریایی - سیستم سوخت و پرایمینگ','Cat Parts Store','https://parts.cat.com/en/catcorp/product/221-0131','Official Compatible Models lists marine C280 and non-marine Gen Set/Petroleum Engine fitment.','REFERENCE','BOTH','Marine Engine and non-marine Gen Set Engine/Petroleum Engine applications are listed.','https://parts.cat.com/en/catcorp/product/221-0131'),
('297-1506','مجموعه خط سوخت Cat 297-1506','Cat Hybrid Fuel Line Assembly transfers fuel between fuel-system components; Compatible Models lists Marine Auxiliary C32, Marine Engine C32 and Petroleum Engine C32.','{C32}','موتورهای دریایی - سیستم سوخت و خطوط سوخت','Cat Parts Store','https://parts.cat.com/en/catcorp/product/297-1506','Official Compatible Models lists Marine Auxiliary, Marine Engine and Petroleum Engine C32.','REFERENCE','BOTH','Marine Auxiliary/Marine Engine and non-marine Petroleum Engine C32 are listed.','https://parts.cat.com/en/catcorp/product/297-1506'),
('472-4908','مجموعه لوله خطوط سوخت Cat 472-4908','Cat Fuel Lines Tube Assembly routes fuel from priming pump to engine; Compatible Models lists Marine Engine C32B/C32/C9/C9.3 and Marine Auxiliary C32B, plus Generator Set C9.3/C32.','{C9,C9.3,C32,C32B}','موتورهای دریایی - سیستم سوخت و خطوط سوخت','Cat Parts Store','https://parts.cat.com/en/catcorp/product/472-4908','Official Compatible Models explicitly lists marine and generator-set applications.','REFERENCE','BOTH','Marine Engine/Auxiliary and non-marine Generator Set/Engine applications are listed.','https://parts.cat.com/en/catcorp/product/472-4908')
